use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/direct-ref-pack";
fn hash(x:&[u8])->String{format!("{:x}",Sha256::digest(x))}
fn u64at(x:&[u8],i:usize)->u64{u64::from_le_bytes(x[i..i+8].try_into().unwrap())}
fn u32at(x:&[u8],i:usize)->u32{u32::from_le_bytes(x[i..i+4].try_into().unwrap())}
fn main(){
    let mut sections=vec![];for ext in["text","rodata","data"]{let f=fs::read(format!("{R}/frozen.{ext}")).unwrap();let n=fs::read(format!("{R}/fresh.{ext}")).unwrap();assert_eq!(f,n);sections.push(json!({"section":format!(".{ext}"),"bytes":f.len(),"identical":true,"sha256":hash(&f)}));}
    let out=Command::new("readelf").args(["-SW",&format!("{R}/frozen-probe")]).output().unwrap();assert!(out.status.success());fs::write(format!("{R}/frozen-readelf-sections.log"),&out.stdout).unwrap();let text=String::from_utf8(out.stdout).unwrap();let line=text.lines().find(|s|s.contains(" .rodata ")).unwrap();let fields:Vec<_>=line[line.find(".rodata").unwrap()..].split_whitespace().collect();let va=u64::from_str_radix(fields[2],16).unwrap();let ro=fs::read(format!("{R}/frozen.rodata")).unwrap();
    let mut a=fs::read(format!("{R}/frozen.data-rel-ro")).unwrap();let mut b=fs::read(format!("{R}/fresh.data-rel-ro")).unwrap();assert_eq!(a.len(),b.len());let mut locations=vec![];
    for i in 0..a.len(){if a[i]==b[i]{continue}assert!(i>=16);let start=i-16;assert_eq!(&a[start..start+16],&b[start..start+16]);let ptr=u64at(&a,start);let len=u64at(&a,start+8)as usize;let offset=ptr.checked_sub(va).unwrap()as usize;assert!(offset+len<=ro.len());let file=std::str::from_utf8(&ro[offset..offset+len]).unwrap();assert!(file.ends_with(".rs"));assert_eq!(u32at(&a,start+20),u32at(&b,start+20));locations.push(json!({"section_offset":start,"file":file,"frozen_line":u32at(&a,start+16),"fresh_line":u32at(&b,start+16),"column":u32at(&a,start+20)}));for j in 16..20{a[start+j]=0;b[start+j]=0;}}
    assert_eq!(a,b);assert_eq!(locations.len(),20);
    let plan:Value=serde_json::from_slice(&fs::read(format!("{R}/capture-plan-final.json")).unwrap()).unwrap();let steps=plan["steps"].as_array().unwrap();let mut inputs=vec![];for n in[200,352]{for block in 0..31{let f=steps.iter().find(|s|s["name"]==format!("b{block}-g2-prefix-{n}-frozen")).unwrap();let p=steps.iter().find(|s|s["name"]==format!("b{block}-g2-prefix-{n}-fresh")).unwrap();assert_eq!(f["environment"],p["environment"]);let x=f["argv"].as_array().unwrap();let y=p["argv"].as_array().unwrap();assert_eq!(&x[..3],&y[..3]);assert_eq!(&x[4..],&y[4..]);}inputs.push(json!({"size":n,"31_command_pairs_identical_except_binary_path":true,"environments_equal":true}));}
    let value=json!({"scope":"offline checks of original saved control binaries/data/commands; no process or timing re-executed","equal_sections":sections,"data_rel_ro_equal_after_masking_only_20_source_line_fields":true,"changed_source_locations":locations,"G2_command_audit":inputs,"whole_executable_hash_equal":false,"G2_control_failure":"fresh/frozen latency3.11x/3.18x at200/352; unchanged outputs/capacities; not a candidate speedup","cause":"unresolved; matching executed-code and constant/data sections rules out an instruction-body change between OFF controls, not all runtime/address-layout/environmental effects","no_timing_repeat":true});fs::write(format!("{R}/control-layout-audit.json"),serde_json::to_vec_pretty(&value).unwrap()).unwrap();println!("OFF.text/.rodata/.data identical; .data.rel.ro differs only20source-location lines; all62G2commands match exceptpath; timing anomaly unresolved");
}
